const results = $input.first().json.results || [];
if (results.length === 0) { return []; } // nothing published yet — end quietly
const r = results[0];
return [{ json: {
  title: r.properties?.Title?.title?.[0]?.plain_text || 'Untitled',
  body: (r.properties?.Body?.rich_text || []).map(t => t.plain_text).join('').slice(0, 6000)
} }];

const src = $('Extract Post').first().json;
const text = ($input.first().json.content?.[0]?.text) || '[]';
const match = text.match(/\[[\s\S]*\]/);
let posts = [];
try { posts = JSON.parse(match ? match[0] : text); } catch (e) { throw new Error('Could not parse social JSON'); }
const allowed = ['Instagram', 'TikTok', 'Threads'];
return posts.filter(p => allowed.includes(p.platform)).map(p => ({ json: {
  title: (src.title + ' — ' + p.platform).slice(0, 200),
  platform: p.platform,
  hook: String(p.hook || '').slice(0, 1900),
  body: String(p.body || '').slice(0, 1900),
  cta: String(p.cta || '').slice(0, 1900),
  hashtags: String(p.hashtags || '').slice(0, 1900)
} }));
